/* Sachgebiet 4a: Straf- und Strafverfahrensrecht. Eigene prüfungsnahe Übungsfragen – keine Original-IHK-Fragen. */
SK.fragen("str", [
  { u: "aufbau", d: 1, q: "Welche drei Elemente müssen vorliegen, damit jemand wegen einer Straftat bestraft werden kann?", o: ["Tatbestandsmäßigkeit, Rechtswidrigkeit und Schuld", ["Anzeige, Anklage und Urteil", "Das sind Verfahrensschritte."], ["Vorsatz, Motiv und Gelegenheit", "Das sind keine Elemente des Deliktsaufbaus."], ["Schaden, Zeuge und Geständnis", "Das sind keine Elemente des Deliktsaufbaus."]], e: "Der dreistufige Deliktsaufbau: Die Handlung erfüllt einen gesetzlichen Tatbestand, ist nicht gerechtfertigt und dem Täter persönlich vorwerfbar.", r: "Deliktsaufbau; §§ 1, 13 ff. StGB" },
  { u: "aufbau", d: 1, q: "Was besagt § 1 StGB?", o: ["Eine Tat kann nur bestraft werden, wenn die Strafbarkeit gesetzlich bestimmt war, bevor die Tat begangen wurde.", ["Jede unmoralische Handlung ist strafbar.", "Strafbar ist nur, was das Gesetz bestimmt."], ["Strafen dürfen rückwirkend eingeführt werden.", "Rückwirkung zulasten des Täters ist verboten."], ["Der Richter darf neue Straftatbestände schaffen.", "Das ist dem Gesetzgeber vorbehalten."]], e: "„Keine Strafe ohne Gesetz“ – auch in Art. 103 Abs. 2 GG verankert.", r: "§ 1 StGB; Art. 103 Abs. 2 GG" },
  { u: "aufbau", d: 1, q: "Was ist ein Verbrechen im Sinne des § 12 StGB?", o: ["Eine rechtswidrige Tat, die im Mindestmaß mit Freiheitsstrafe von einem Jahr oder darüber bedroht ist", ["Jede Straftat mit Gewalt", "Maßgeblich ist die Mindeststrafe, nicht die Art der Tat."], ["Jede Tat mit einem Schaden über 1.000 Euro", "Auf die Schadenshöhe kommt es nicht an."], ["Jede Tat, die mit Freiheitsstrafe bedroht ist", "Auch Vergehen können mit Freiheitsstrafe bedroht sein."]], e: "Vergehen sind Taten mit geringerer Mindestfreiheitsstrafe oder Geldstrafe.", r: "§ 12 StGB" },
  { u: "aufbau", t: "zu", d: 2, q: "Ordne die Delikte richtig ein.", p: [["Raub (§ 249 StGB)", "Verbrechen"], ["Diebstahl (§ 242 StGB)", "Vergehen"], ["Meineid (§ 154 StGB)", "Verbrechen – Mindeststrafe ein Jahr"], ["Hausfriedensbruch (§ 123 StGB)", "Vergehen – Antragsdelikt"]], e: "Raub und Meineid haben eine Mindeststrafe von einem Jahr und sind Verbrechen. Diebstahl und Hausfriedensbruch sind Vergehen." },
  { u: "aufbau", d: 1, q: "Ab welchem Alter ist ein Mensch strafmündig?", o: ["Ab 14 Jahren", ["Ab 7 Jahren", "Mit 7 beginnt die beschränkte Deliktsfähigkeit im Zivilrecht."], ["Ab 16 Jahren", "Die Grenze liegt bei 14."], ["Ab 18 Jahren", "Ab 18 gilt man als Heranwachsender, strafmündig ist man früher."]], e: "§ 19 StGB: Schuldunfähig ist, wer bei Begehung der Tat noch nicht vierzehn Jahre alt ist.", r: "§ 19 StGB" },
  { u: "aufbau", d: 2, q: "Was bedeutet Vorsatz?", o: ["Wissen und Wollen der Verwirklichung des Tatbestands", ["Das Außerachtlassen der gebotenen Sorgfalt", "Das ist Fahrlässigkeit."], ["Jede Handlung mit schlimmen Folgen", "Auf die Folgen allein kommt es nicht an."], ["Das Handeln auf Befehl", "Das ist keine Definition des Vorsatzes."]], e: "Es genügt, dass der Täter den Erfolg für möglich hält und billigend in Kauf nimmt (bedingter Vorsatz).", r: "§ 15 StGB" },
  { u: "aufbau", d: 2, q: "Wann ist fahrlässiges Handeln strafbar?", o: ["Nur wenn das Gesetz fahrlässiges Handeln ausdrücklich mit Strafe bedroht", ["Immer", "§ 15 StGB verlangt eine ausdrückliche Anordnung."], ["Nie", "Es gibt Fahrlässigkeitsdelikte, z. B. § 229 StGB."], ["Nur bei Schäden über 500 Euro", "Auf die Schadenshöhe kommt es nicht an."]], e: "§ 15 StGB: Strafbar ist nur vorsätzliches Handeln, wenn nicht das Gesetz fahrlässiges Handeln ausdrücklich mit Strafe bedroht.", r: "§ 15 StGB" },
  { u: "aufbau", d: 3, q: "Unter welcher Voraussetzung ist das Unterlassen einer Handlung nach § 13 StGB strafbar wie aktives Tun?", o: ["Wenn der Täter rechtlich dafür einzustehen hat, dass der Erfolg nicht eintritt (Garantenstellung)", ["Immer, wenn jemand zusieht", "Ohne Garantenstellung kommt nur § 323c StGB in Betracht."], ["Nur wenn der Täter verwandt mit dem Opfer ist", "Eine Garantenstellung kann auch aus Vertrag oder Vorverhalten folgen."], ["Nie", "§ 13 StGB sieht die Strafbarkeit ausdrücklich vor."]], e: "Wachpersonen können aus dem Bewachungsvertrag bzw. ihrer tatsächlichen Übernahme Garanten für das bewachte Objekt sein.", r: "§ 13 StGB" },
  { u: "aufbau", d: 2, f: 1, q: "Eine Wachperson beobachtet bei ihrem Rundgang, wie Unbekannte Kupferkabel vom bewachten Gelände tragen. Sie unternimmt nichts und meldet es nicht. Wie ist das einzuordnen?", o: ["Sie kann sich wegen Beihilfe bzw. Begehung durch Unterlassen strafbar machen, weil sie Garantin für das Objekt ist.", ["Sie bleibt straffrei, weil sie nichts getan hat.", "Gerade das Nichtstun ist der Vorwurf."], ["Strafbar ist nur der Auftraggeber.", "Der Auftraggeber ist der Geschädigte."], ["Es liegt nur ein Verstoß gegen die Hausordnung vor.", "Es geht um eine Straftat am bewachten Eigentum."]], e: "Wer vertraglich den Schutz übernommen hat, muss zumutbare Maßnahmen ergreifen – mindestens melden und alarmieren.", r: "§ 13 StGB; §§ 242, 27 StGB" },
  { u: "aufbau", t: "mc", d: 2, q: "Welche zwei Umstände können die Schuld ausschließen?", o: ["Der Täter ist noch nicht 14 Jahre alt.", "Der Täter ist wegen einer krankhaften seelischen Störung unfähig, das Unrecht der Tat einzusehen.", ["Der Täter kannte das Opfer nicht.", "Das berührt die Schuld nicht."], ["Der Täter hat die Tat später bereut.", "Reue kann die Strafe mildern, schließt die Schuld aber nicht aus."]], e: "Schuldunfähigkeit regeln § 19 StGB (Kinder) und § 20 StGB (seelische Störungen).", r: "§§ 19, 20 StGB" },
  { u: "aufbau", t: "tf", d: 1, a: true, q: "Eine Tat, die durch Notwehr gerechtfertigt ist, ist nicht rechtswidrig und damit nicht strafbar.", e: "Rechtfertigungsgründe lassen die Rechtswidrigkeit entfallen.", r: "§ 32 StGB" },
  { u: "aufbau", t: "tf", d: 2, a: false, q: "Weil ein 13-Jähriger schuldunfähig ist, darf man sich gegen seinen Angriff nicht verteidigen.", e: "Auch der Angriff eines Kindes ist rechtswidrig. Notwehr ist möglich, aber eingeschränkt: Ausweichen und schonende Abwehr haben Vorrang.", r: "§§ 19, 32 StGB" },
  { u: "aufbau", t: "fa", d: 2, q: "Erkläre den dreistufigen Aufbau einer Straftat.", m: "Erste Stufe ist die Tatbestandsmäßigkeit: Das Verhalten erfüllt alle objektiven und subjektiven Merkmale eines Strafgesetzes, z. B. Wegnahme einer fremden beweglichen Sache in Zueignungsabsicht. Zweite Stufe ist die Rechtswidrigkeit: Sie ist durch die Tatbestandserfüllung indiziert und entfällt, wenn ein Rechtfertigungsgrund wie Notwehr, Notstand oder Festnahmerecht eingreift. Dritte Stufe ist die Schuld: Die Tat muss dem Täter persönlich vorwerfbar sein; sie fehlt z. B. bei Kindern unter 14 Jahren oder bei Schuldunfähigkeit nach § 20 StGB.", c: ["Tatbestand", "Rechtswidrigkeit / Rechtfertigungsgründe", "Schuld / Schuldunfähigkeit"] },

  { u: "versuch", d: 2, q: "Wann beginnt der Versuch einer Straftat (§ 22 StGB)?", o: ["Wenn der Täter nach seiner Vorstellung von der Tat zur Verwirklichung des Tatbestands unmittelbar ansetzt", ["Mit dem ersten Gedanken an die Tat", "Gedanken sind straflos."], ["Mit dem Kauf eines Werkzeugs", "Das ist in der Regel bloße Vorbereitung."], ["Erst wenn die Tat vollendet ist", "Dann liegt Vollendung vor, kein Versuch."]], e: "Zwischen straffreier Vorbereitung und strafbarem Versuch liegt das unmittelbare Ansetzen.", r: "§ 22 StGB" },
  { u: "versuch", d: 2, q: "Wann ist der Versuch strafbar (§ 23 StGB)?", o: ["Bei Verbrechen stets, bei Vergehen nur, wenn das Gesetz es ausdrücklich bestimmt", ["Immer", "Bei Vergehen bedarf es einer ausdrücklichen Regelung."], ["Nie", "Der Versuch ist in vielen Fällen strafbar."], ["Nur bei Schäden über 1.000 Euro", "Die Schadenshöhe ist kein Kriterium."]], e: "Der versuchte Diebstahl ist z. B. strafbar, weil § 242 Abs. 2 StGB es bestimmt.", r: "§ 23 StGB" },
  { u: "versuch", d: 3, f: 1, q: "Ein Mann hebelt nachts am Fenster eines Lagers. Als er die Taschenlampe der Wachperson sieht, flieht er ohne Beute. Welche Tat kommt in Betracht?", o: ["Versuchter Diebstahl in einem besonders schweren Fall und Sachbeschädigung", ["Keine Straftat, weil nichts weggenommen wurde", "Der Versuch ist strafbar."], ["Vollendeter Raub", "Es fehlt Gewalt gegen eine Person und die Wegnahme."], ["Unterschlagung", "Es wurde nichts zugeeignet."]], e: "Mit dem Aufhebeln hat er unmittelbar angesetzt. Die Flucht aus Angst vor Entdeckung ist kein freiwilliger Rücktritt.", r: "§§ 242, 243, 22, 23, 303 StGB" },
  { u: "versuch", d: 2, q: "Wie wird ein Anstifter bestraft (§ 26 StGB)?", o: ["Gleich einem Täter", ["Gar nicht", "Anstiftung ist strafbar."], ["Immer nur mit Geldstrafe", "Der Strafrahmen richtet sich nach der Haupttat."], ["Nur, wenn er am Tatort war", "Anwesenheit ist nicht erforderlich."]], e: "Anstifter ist, wer vorsätzlich einen anderen zu dessen vorsätzlich begangener rechtswidriger Tat bestimmt hat.", r: "§ 26 StGB" },
  { u: "versuch", d: 2, f: 1, q: "Eine Wachperson verrät einem Bekannten gegen Geld, wann der Alarm im Lager abgeschaltet ist. Der Bekannte bricht daraufhin ein. Wie ist die Wachperson beteiligt?", o: ["Sie leistet Beihilfe zum Einbruchdiebstahl.", ["Sie ist unbeteiligt, weil sie nicht am Tatort war.", "Beihilfe setzt keine Anwesenheit voraus."], ["Sie ist nur Zeugin.", "Sie hat die Tat gefördert."], ["Sie begeht nur eine Ordnungswidrigkeit.", "Beihilfe zu einer Straftat ist selbst strafbar."]], e: "Gehilfe ist, wer vorsätzlich einem anderen zu dessen vorsätzlicher rechtswidriger Tat Hilfe leistet. Je nach Tatbeitrag kommt auch Mittäterschaft in Betracht.", r: "§ 27 StGB" },
  { u: "versuch", t: "mc", d: 2, q: "Welche zwei Formen gehören zur Teilnahme (nicht zur Täterschaft)?", o: ["Anstiftung", "Beihilfe", ["Mittäterschaft", "Mittäter sind Täter (§ 25 Abs. 2 StGB)."], ["Mittelbare Täterschaft", "Auch der mittelbare Täter ist Täter."]], e: "Täterschaft regelt § 25 StGB, Teilnahme die §§ 26 und 27 StGB.", r: "§§ 25–27 StGB" },
  { u: "versuch", t: "tf", d: 2, a: true, q: "Wer freiwillig die weitere Ausführung der Tat aufgibt, wird nicht wegen Versuchs bestraft.", e: "Das ist der strafbefreiende Rücktritt (§ 24 StGB). Bereits vollendete andere Taten, etwa eine Sachbeschädigung, bleiben strafbar.", r: "§ 24 StGB" },
  { u: "versuch", t: "tf", d: 1, a: false, q: "Die Strafe für den Gehilfen ist immer genauso hoch wie für den Täter.", e: "Die Strafe des Gehilfen ist nach § 27 Abs. 2 StGB zu mildern.", r: "§ 27 StGB" },

  { u: "notwehr", d: 1, q: "Wie definiert § 32 StGB die Notwehr?", o: ["Die Verteidigung, die erforderlich ist, um einen gegenwärtigen rechtswidrigen Angriff von sich oder einem anderen abzuwenden", ["Jede Gewalt gegen einen Straftäter", "Erforderlich ist ein gegenwärtiger Angriff und eine erforderliche Verteidigung."], ["Das Recht, einen Dieb zu bestrafen", "Bestrafen ist Sache des Staates."], ["Die Abwehr einer Naturgefahr", "Notwehr setzt einen menschlichen Angriff voraus."]], e: "Wer eine durch Notwehr gebotene Tat begeht, handelt nicht rechtswidrig.", r: "§ 32 StGB" },
  { u: "notwehr", d: 2, q: "Wann ist ein Angriff „gegenwärtig“?", o: ["Wenn er unmittelbar bevorsteht, gerade stattfindet oder noch andauert", ["Wenn er für die nächste Woche angedroht wurde", "Ein künftiger Angriff ist nicht gegenwärtig."], ["Wenn er gestern stattgefunden hat", "Ein abgeschlossener Angriff ist nicht mehr gegenwärtig."], ["Wenn der Verteidiger ihn befürchtet", "Bloße Befürchtung genügt nicht."]], e: "Beim Diebstahl dauert der Angriff an, solange der Täter mit der Beute flieht und sie noch nicht gesichert hat.", r: "§ 32 StGB" },
  { u: "notwehr", t: "mc", d: 2, q: "Welche zwei Rechtsgüter sind notwehrfähig?", o: ["Körperliche Unversehrtheit", "Eigentum", ["Die öffentliche Ordnung als solche", "Rechtsgüter der Allgemeinheit sind nicht notwehrfähig."], ["Die Straßenverkehrsordnung", "Die Rechtsordnung als solche darf der Einzelne nicht per Notwehr verteidigen."]], e: "Notwehrfähig sind Individualrechtsgüter: Leben, Gesundheit, Freiheit, Ehre, Eigentum, Besitz, Hausrecht.", r: "§ 32 StGB" },
  { u: "notwehr", d: 2, f: 1, q: "Ein Betrunkener holt im Foyer mit einer Flasche zum Schlag gegen die Wachperson aus. Sie stößt ihn weg; er stürzt und verstaucht sich die Hand. Wie ist das zu bewerten?", o: ["Gerechtfertigt durch Notwehr: Der Angriff war gegenwärtig und rechtswidrig, das Wegstoßen war erforderlich.", ["Strafbare Körperverletzung, weil der Mann verletzt wurde", "Die Verletzung ist durch Notwehr gerechtfertigt."], ["Nur gerechtfertigt, wenn vorher die Polizei gerufen wurde", "Bei einem gegenwärtigen Angriff ist das nicht möglich."], ["Unzulässig, weil Betrunkene nicht angegriffen werden dürfen", "Die Wachperson greift nicht an, sie verteidigt sich."]], e: "Auch gegen erkennbar Betrunkene ist Notwehr zulässig; das Wegstoßen ist ein mildes Mittel.", r: "§ 32 StGB" },
  { u: "notwehr", d: 3, f: 1, q: "Nachdem die Wachperson einen Angreifer zu Boden gebracht hat, bleibt dieser regungslos liegen. Sie tritt noch zweimal zu, „damit er es lernt“. Wie ist das zu bewerten?", o: ["Die Tritte sind nicht mehr durch Notwehr gedeckt; es liegt eine strafbare Körperverletzung vor.", ["Alles ist durch Notwehr gedeckt, weil er angefangen hat.", "Die Notwehr endet mit dem Angriff."], ["Die Tritte sind als Nothilfe gerechtfertigt.", "Es gibt keinen Angriff mehr, der abzuwehren wäre."], ["Die Tritte sind eine zulässige Bestrafung.", "Bestrafen darf nur der Staat."]], e: "Der Angriff ist beendet. Wer danach weiter einwirkt, verteidigt nicht mehr, sondern übt Vergeltung.", r: "§§ 32, 223 StGB" },
  { u: "notwehr", d: 2, q: "Was regelt § 33 StGB?", o: ["Wer die Grenzen der Notwehr aus Verwirrung, Furcht oder Schrecken überschreitet, wird nicht bestraft.", ["Wer aus Wut zu hart zuschlägt, bleibt straffrei.", "Wut und Zorn sind nicht erfasst."], ["Notwehr ist nur Polizeibeamten erlaubt.", "Notwehr steht jedermann zu."], ["Notwehr ist nur bei Angriffen auf das Leben erlaubt.", "Auch andere Rechtsgüter sind notwehrfähig."]], e: "Der Notwehrexzess entschuldigt nur bei den sogenannten asthenischen Affekten.", r: "§ 33 StGB" },
  { u: "notwehr", d: 3, q: "In welchem Fall ist das Notwehrrecht eingeschränkt?", o: ["Bei einem krassen Missverhältnis zwischen dem verteidigten Rechtsgut und der Verletzung des Angreifers", ["Wenn der Angreifer größer ist als der Verteidiger", "Das schränkt die Notwehr nicht ein."], ["Wenn der Angriff bei Nacht erfolgt", "Die Tageszeit spielt keine Rolle."], ["Wenn der Verteidiger eine Wachperson ist", "Der Beruf schränkt das Recht nicht ein."]], e: "Die Notwehr muss „geboten“ sein. Einschränkungen gelten u. a. bei Bagatellangriffen, bei Angriffen von Kindern oder erkennbar Schuldunfähigen und bei provozierten Angriffen.", r: "§ 32 StGB (Gebotenheit)" },
  { u: "notwehr", t: "mc", d: 2, q: "Welche zwei Aussagen zur Nothilfe sind richtig?", o: ["Sie ist Notwehr zugunsten eines anderen.", "Für sie gelten dieselben Voraussetzungen wie für die Notwehr.", ["Sie ist nur Angehörigen des Opfers erlaubt.", "Jeder darf Nothilfe leisten."], ["Sie setzt voraus, dass der Helfer Wachperson ist.", "Sie ist ein Jedermannsrecht."]], e: "§ 32 Abs. 2 StGB: „von sich oder einem anderen“.", r: "§ 32 StGB" },
  { u: "notwehr", t: "tf", d: 2, a: false, q: "Wer angegriffen wird, muss grundsätzlich zuerst fliehen, bevor er sich verteidigen darf.", e: "Das Recht braucht dem Unrecht nicht zu weichen. Eine Ausweichpflicht besteht nur in den Fällen eingeschränkter Notwehr, z. B. gegenüber Kindern.", r: "§ 32 StGB" },
  { u: "notwehr", t: "tf", d: 2, a: false, q: "Gegen eine rechtmäßige Festnahme durch die Polizei darf man sich mit Notwehr wehren.", e: "Notwehr setzt einen rechtswidrigen Angriff voraus. Rechtmäßiges hoheitliches Handeln ist kein rechtswidriger Angriff.", r: "§ 32 StGB" },
  { u: "notwehr", t: "fa", d: 2, q: "Nenne die Voraussetzungen der Notwehr nach § 32 StGB.", m: "Notwehrlage: ein Angriff, also die Bedrohung eines Rechtsguts durch menschliches Verhalten; der Angriff ist gegenwärtig (steht unmittelbar bevor, findet statt oder dauert noch an) und rechtswidrig. Notwehrhandlung: Die Verteidigung richtet sich gegen den Angreifer, ist geeignet und erforderlich, d. h. das mildeste sicher wirksame Mittel, und sie ist geboten, also nicht rechtsmissbräuchlich. Subjektiv handelt der Verteidiger mit Verteidigungswillen.", c: ["Angriff auf ein Rechtsgut", "gegenwärtig", "rechtswidrig", "erforderliche Verteidigung", "Gebotenheit", "Verteidigungswille"] },

  { u: "notstand", d: 2, q: "Was setzt der rechtfertigende Notstand (§ 34 StGB) voraus?", o: ["Eine gegenwärtige, nicht anders abwendbare Gefahr für ein Rechtsgut, wobei das geschützte Interesse das beeinträchtigte wesentlich überwiegt", ["Einen rechtswidrigen Angriff eines Menschen", "Das ist die Voraussetzung der Notwehr."], ["Einen zivilrechtlichen Anspruch", "Das ist die Voraussetzung der Selbsthilfe."], ["Eine frische Tat", "Das ist die Voraussetzung der vorläufigen Festnahme."]], e: "Außerdem muss die Tat ein angemessenes Mittel sein, die Gefahr abzuwenden.", r: "§ 34 StGB" },
  { u: "notstand", d: 2, f: 1, q: "Im bewachten Gebäude ist eine Person in einem brennenden Raum eingeschlossen. Die Wachperson tritt die verschlossene Tür ein. Welcher Rechtfertigungsgrund greift strafrechtlich?", o: ["Rechtfertigender Notstand (§ 34 StGB)", ["Notwehr (§ 32 StGB)", "Es fehlt ein menschlicher Angriff."], ["Vorläufige Festnahme (§ 127 StPO)", "Es wird niemand festgenommen."], ["Notwehrexzess (§ 33 StGB)", "Es liegt keine Notwehr vor."]], e: "Das Leben überwiegt das Eigentum an der Tür wesentlich. Die Sachbeschädigung ist gerechtfertigt.", r: "§ 34 StGB" },
  { u: "notstand", d: 3, q: "Worin unterscheidet sich der entschuldigende Notstand (§ 35 StGB) vom rechtfertigenden Notstand?", o: ["Die Tat bleibt rechtswidrig, der Täter handelt aber ohne Schuld – geschützt sind Leben, Leib oder Freiheit von ihm selbst, Angehörigen oder nahestehenden Personen.", ["Er gilt nur für Sachgefahren.", "§ 35 StGB betrifft Leben, Leib und Freiheit."], ["Er setzt ein wesentlich überwiegendes Interesse voraus.", "Das verlangt § 34 StGB, nicht § 35 StGB."], ["Er gilt für jedermann zugunsten beliebiger Dritter.", "Der Personenkreis ist begrenzt."]], e: "§ 34 StGB rechtfertigt, § 35 StGB entschuldigt.", r: "§§ 34, 35 StGB" },
  { u: "notstand", t: "mc", d: 2, q: "Welche zwei Merkmale gehören zum rechtfertigenden Notstand?", o: ["Die Gefahr ist nicht anders abwendbar.", "Das geschützte Interesse überwiegt das beeinträchtigte wesentlich.", ["Die Gefahr muss von einem Menschen schuldhaft verursacht sein.", "Die Quelle der Gefahr ist gleichgültig."], ["Die Tat muss vorher angekündigt werden.", "Eine Ankündigung ist nicht erforderlich."]], e: "Notstand verlangt eine Güter- und Interessenabwägung.", r: "§ 34 StGB" },
  { u: "notstand", t: "tf", d: 2, a: true, q: "Beim rechtfertigenden Notstand kann die Gefahr auch von Naturereignissen, Tieren oder Sachen ausgehen.", e: "Anders als die Notwehr setzt der Notstand keinen menschlichen Angriff voraus.", r: "§ 34 StGB" },
  { u: "notstand", d: 2, f: 1, q: "Eine Wachperson fährt einen bewusstlosen Kollegen mit dem Privatwagen eines abwesenden Mitarbeiters zum nahen Krankenhaus, weil kein Rettungswagen verfügbar ist. Der unbefugte Gebrauch des Fahrzeugs ist …", o: ["durch Notstand gerechtfertigt, wenn die Gefahr nicht anders abwendbar war.", ["immer strafbar nach § 248b StGB.", "Ein Rechtfertigungsgrund kann die Strafbarkeit ausschließen."], ["durch Notwehr gerechtfertigt.", "Es fehlt ein Angriff."], ["durch Selbsthilfe gerechtfertigt.", "Es wird kein Anspruch gesichert."]], e: "Leben und Gesundheit überwiegen das Gebrauchsrecht am Fahrzeug wesentlich.", r: "§ 34 StGB" },
  { u: "notstand", t: "fa", d: 3, q: "Grenze Notwehr (§ 32 StGB) und rechtfertigenden Notstand (§ 34 StGB) voneinander ab.", m: "Notwehr setzt einen gegenwärtigen rechtswidrigen Angriff eines Menschen voraus; die Verteidigung richtet sich gegen den Angreifer. Eine Güterabwägung findet grundsätzlich nicht statt, die Verteidigung muss nur erforderlich und geboten sein. Notstand setzt eine gegenwärtige Gefahr gleich welcher Herkunft voraus, die nicht anders abwendbar ist. Eingegriffen wird meist in Rechtsgüter Unbeteiligter. Deshalb ist eine Abwägung nötig: Das geschützte Interesse muss das beeinträchtigte wesentlich überwiegen, und die Tat muss ein angemessenes Mittel sein.", c: ["Angriff vs. Gefahr", "Eingriff gegen Angreifer vs. Unbeteiligte", "keine Güterabwägung vs. wesentliches Überwiegen", "Erforderlichkeit / nicht anders abwendbar"] },

  { u: "festnahme", d: 1, q: "Wer darf nach § 127 Abs. 1 StPO eine Person vorläufig festnehmen?", o: ["Jedermann", ["Nur Polizeibeamte", "Absatz 1 richtet sich ausdrücklich an jedermann."], ["Nur Wachpersonen mit Sachkundeprüfung", "Die Qualifikation spielt keine Rolle."], ["Nur der Geschädigte", "Auch unbeteiligte Dritte dürfen festnehmen."]], e: "§ 127 Abs. 1 StPO ist das klassische Jedermannsrecht.", r: "§ 127 Abs. 1 StPO" },
  { u: "festnahme", d: 2, q: "Welche Voraussetzungen hat die vorläufige Festnahme durch jedermann?", o: ["Die Person wird auf frischer Tat betroffen oder verfolgt und ist der Flucht verdächtig oder ihre Identität kann nicht sofort festgestellt werden.", ["Es genügt ein allgemeiner Verdacht gegen die Person.", "Erforderlich ist eine frische Tat."], ["Die Person muss vorbestraft sein.", "Das ist keine Voraussetzung."], ["Die Tat muss ein Verbrechen sein.", "Auch Vergehen genügen."]], e: "Beide Elemente müssen vorliegen: frische Tat und ein Festnahmegrund (Fluchtverdacht oder nicht feststellbare Identität).", r: "§ 127 Abs. 1 StPO" },
  { u: "festnahme", d: 2, f: 1, q: "Ein Ladendetektiv stellt einen Dieb hinter der Kasse. Der Mann zeigt freiwillig seinen Personalausweis und bleibt ruhig stehen. Darf er festgenommen werden?", o: ["Nein, wenn die Identität feststeht und kein Fluchtverdacht besteht, fehlt der Festnahmegrund.", ["Ja, bei jedem Diebstahl", "Die frische Tat allein genügt nicht."], ["Ja, zur Bestrafung", "Die Festnahme dient nur der Sicherung der Strafverfolgung."], ["Ja, bis der Geschäftsführer Zeit hat", "Das ist kein gesetzlicher Grund."]], e: "Der Detektiv notiert die Personalien, sichert die Ware und kann Anzeige erstatten. Für ein Festhalten fehlt die Grundlage.", r: "§ 127 Abs. 1 StPO" },
  { u: "festnahme", d: 2, q: "Was ist nach einer vorläufigen Festnahme durch eine Privatperson zu tun?", o: ["Die Person ist unverzüglich der Polizei zu übergeben.", ["Die Person ist zu vernehmen.", "Vernehmungen führen nur die Strafverfolgungsbehörden."], ["Die Person ist zu durchsuchen.", "Durchsuchungen sind hoheitliche Maßnahmen."], ["Die Person ist bis Geschäftsschluss festzuhalten.", "Das Festhalten darf nur so lange dauern wie nötig."]], e: "Die Festnahme dient allein dazu, die Person den Strafverfolgungsbehörden zuzuführen.", r: "§ 127 Abs. 1 StPO; Art. 104 GG" },
  { u: "festnahme", t: "mc", d: 2, q: "Welche zwei Maßnahmen sind einer Wachperson nach einer vorläufigen Festnahme nicht erlaubt?", o: ["Durchsuchung der Kleidung gegen den Willen des Festgenommenen", "Vernehmung mit Druck, um ein Geständnis zu erhalten", ["Verständigung der Polizei", "Das ist geboten."], ["Bitte, in einem Büro auf die Polizei zu warten", "Das ist zulässig und schont die Person."]], e: "Durchsuchung und Vernehmung sind der Polizei vorbehalten. Druck kann als Nötigung strafbar sein.", r: "§ 127 StPO; § 240 StGB" },
  { u: "festnahme", d: 3, q: "Welche Gewalt ist bei der Festnahme nach § 127 Abs. 1 StPO zulässig?", o: ["Festhalten und angemessener körperlicher Zwang, soweit zur Festnahme erforderlich", ["Jede Gewalt einschließlich lebensgefährlicher Mittel", "Lebensgefährdende Gewalt deckt das Festnahmerecht nicht."], ["Gar keine – nur Zureden", "Festhalten ist zulässig, sonst liefe das Recht leer."], ["Nur Fesselung mit Handschellen", "Fesselung ist nur ausnahmsweise bei Erforderlichkeit zulässig."]], e: "Das Festnahmerecht umfasst die zur Festnahme notwendigen, verhältnismäßigen Mittel. Wehrt sich der Festgenommene mit Gewalt, kommt zusätzlich Notwehr in Betracht.", r: "§ 127 Abs. 1 StPO" },
  { u: "festnahme", d: 3, f: 1, q: "Ein zwölfjähriges Kind wird beim Ladendiebstahl beobachtet. Welche Vorgehensweise ist richtig?", o: ["Kind ansprechen, Ware sichern, Erziehungsberechtigte bzw. Polizei verständigen und das Kind in deren Obhut übergeben", ["Das Kind wie einen Erwachsenen nach § 127 StPO festnehmen und fesseln", "Kinder sind schuldunfähig; ob § 127 StPO überhaupt anwendbar ist, ist umstritten. Fesseln wäre in jedem Fall unverhältnismäßig."], ["Das Kind laufen lassen und nichts unternehmen", "Die Ware darf gesichert und die Aufsicht informiert werden."], ["Das Kind zur Strafe im Lager einsperren", "Das wäre Freiheitsberaubung."]], e: "Kinder unter 14 sind nicht strafmündig. Die Rechtslage zum Festnahmerecht ist umstritten; Besitzkehr für die Ware bleibt möglich. Schonendes Vorgehen ist zwingend.", r: "§ 19 StGB; § 127 StPO; § 859 BGB" },
  { u: "festnahme", t: "mc", d: 2, q: "In welchen zwei Fällen fehlt die „frische Tat“?", o: ["Der Detektiv erkennt einen Kunden wieder, der vor drei Tagen gestohlen haben soll.", "Eine Kollegin vermutet nur, dass jemand etwas eingesteckt haben könnte.", ["Der Täter wird beim Einstecken der Ware beobachtet und am Ausgang gestellt.", "Das ist der klassische Fall der frischen Tat."], ["Der Täter wird unmittelbar nach der Tat ohne Unterbrechung verfolgt.", "Auch die Verfolgung auf frischer Tat genügt."]], e: "Frische Tat erfordert einen engen zeitlichen und räumlichen Zusammenhang und sichere Wahrnehmung.", r: "§ 127 Abs. 1 StPO" },
  { u: "festnahme", t: "tf", d: 2, a: false, q: "Bei einer Ordnungswidrigkeit, etwa Falschparken, besteht ein Festnahmerecht nach § 127 Abs. 1 StPO.", e: "§ 127 StPO setzt eine Straftat voraus. Bei Ordnungswidrigkeiten gibt es kein Jedermann-Festnahmerecht.", r: "§ 127 StPO; § 46 OWiG" },
  { u: "festnahme", t: "tf", d: 2, a: true, q: "Die Identitätsfeststellung selbst bleibt nach § 127 Abs. 1 Satz 2 StPO der Staatsanwaltschaft und der Polizei vorbehalten.", e: "Die Feststellung der Identität richtet sich nach § 163b StPO. Private dürfen nur festhalten, bis die Polizei kommt.", r: "§§ 127 Abs. 1, 163b StPO" },
  { u: "festnahme", d: 3, f: 1, q: "Eine Wachperson hält einen Mann fest, weil sie irrtümlich meint, er habe gestohlen. Tatsächlich war er unschuldig; der Irrtum beruhte auf mangelnder Sorgfalt. Welche Folgen drohen?", o: ["Strafbarkeit wegen Freiheitsberaubung oder Nötigung kommt in Betracht, dazu Schadensersatz und Schmerzensgeld.", ["Keine, weil sie in guter Absicht handelte", "Gute Absicht ersetzt die gesetzlichen Voraussetzungen nicht."], ["Nur eine Verwarnung durch die IHK", "Die IHK ist dafür nicht zuständig."], ["Der Mann muss die Kosten des Einsatzes tragen", "Er ist der Geschädigte."]], e: "Wer festnimmt, trägt das Risiko. Deshalb nur bei sicherer eigener Wahrnehmung handeln.", r: "§§ 239, 240 StGB; § 823 BGB" },
  { u: "festnahme", t: "fa", d: 2, f: 1, q: "Du beobachtest als Ladendetektiv, wie eine Kundin eine Jacke unter ihren Mantel steckt und das Geschäft verlässt. Beschreibe dein Vorgehen und die Rechtsgrundlagen.", m: "Ich spreche die Kundin nach dem Passieren des Kassenbereichs ruhig an, stelle mich vor und bitte sie, mich ins Büro zu begleiten. Die Tat ist frisch, ich habe sie selbst beobachtet. Die Ware sichere ich im Wege der Besitzkehr (§§ 859 Abs. 2, 860 BGB). Ich bitte um einen Ausweis. Weist sie sich nicht aus oder will sie fliehen, halte ich sie nach § 127 Abs. 1 StPO mit angemessenen Mitteln fest und verständige sofort die Polizei. Ich durchsuche sie nicht und vernehme sie nicht. Nach Möglichkeit ziehe ich eine Zeugin hinzu. Ich übergebe sie der Polizei, fertige einen Bericht und der Hausrechtsinhaber entscheidet über Strafantrag und Hausverbot.", c: ["sichere Beobachtung, frische Tat", "ruhige Ansprache", "Besitzkehr für die Ware", "§ 127 Abs. 1 StPO nur bei Fluchtverdacht / unbekannter Identität", "keine Durchsuchung, keine Vernehmung", "Polizei, Dokumentation"] },

  { u: "ordnung", d: 1, q: "Wer begeht Hausfriedensbruch (§ 123 StGB)?", o: ["Wer in die Wohnung, die Geschäftsräume oder das befriedete Besitztum eines anderen widerrechtlich eindringt oder sich auf Aufforderung des Berechtigten nicht entfernt", ["Wer in einem Geschäft laut spricht", "Das allein erfüllt den Tatbestand nicht."], ["Wer ein Haus fotografiert", "Fotografieren ist kein Eindringen."], ["Wer an einer Haustür klingelt", "Klingeln ist kein Eindringen."]], e: "Zwei Varianten: widerrechtliches Eindringen und unbefugtes Verweilen trotz Aufforderung.", r: "§ 123 StGB" },
  { u: "ordnung", d: 2, q: "Wie wird Hausfriedensbruch verfolgt?", o: ["Nur auf Antrag", ["Immer von Amts wegen", "§ 123 Abs. 2 StGB verlangt einen Strafantrag."], ["Nur, wenn ein Schaden entstanden ist", "Ein Schaden ist nicht erforderlich."], ["Gar nicht – es ist eine Ordnungswidrigkeit", "Es ist eine Straftat."]], e: "Hausfriedensbruch ist ein absolutes Antragsdelikt. Antragsberechtigt ist der Inhaber des Hausrechts.", r: "§ 123 Abs. 2 StGB" },
  { u: "ordnung", d: 2, f: 1, q: "Eine Wachperson stoppt auf dem Firmenparkplatz einen Fahrer, behauptet, sie sei „von der Polizei“, und verlangt Führerschein und Fahrzeugschein. Welcher Tatbestand kommt in Betracht?", o: ["Amtsanmaßung (§ 132 StGB)", ["Hausfriedensbruch (§ 123 StGB)", "Sie dringt nirgends ein."], ["Diebstahl (§ 242 StGB)", "Sie nimmt nichts weg."], ["Unterlassene Hilfeleistung (§ 323c StGB)", "Es liegt kein Unglücksfall vor."]], e: "Wer sich unbefugt mit der Ausübung eines öffentlichen Amtes befasst oder eine Handlung vornimmt, die nur kraft eines öffentlichen Amtes vorgenommen werden darf, macht sich strafbar.", r: "§ 132 StGB" },
  { u: "ordnung", d: 2, q: "Was stellt § 132a StGB unter Strafe?", o: ["Das unbefugte Führen von Amts- und Dienstbezeichnungen, Titeln sowie das unbefugte Tragen von Uniformen und Amtsabzeichen", ["Das Tragen von Dienstkleidung eines Sicherheitsunternehmens", "Das ist zulässig, solange keine Verwechslungsgefahr besteht."], ["Das Verlieren des Dienstausweises", "Das ist keine Straftat nach § 132a StGB."], ["Das Tragen eines Namensschilds", "Das ist teils sogar vorgeschrieben."]], e: "Auch zum Verwechseln ähnliche Uniformen und Abzeichen sind erfasst – deshalb die Regeln zur Dienstkleidung in § 19 BewachV.", r: "§ 132a StGB; § 19 BewachV" },
  { u: "ordnung", t: "mc", d: 2, q: "Welche zwei Orte schützt § 123 StGB?", o: ["Geschäftsräume", "Befriedetes Besitztum", ["Öffentliche Straßen", "Dort besteht kein Hausrecht."], ["Öffentliche Parks ohne Einfriedung", "Sie sind kein befriedetes Besitztum."]], e: "Geschützt sind Wohnung, Geschäftsräume, befriedetes Besitztum und abgeschlossene Räume, die zum öffentlichen Dienst oder Verkehr bestimmt sind.", r: "§ 123 StGB" },
  { u: "ordnung", t: "tf", d: 2, a: true, q: "Wer ein Kaufhaus während der Öffnungszeit betritt, obwohl gegen ihn ein Hausverbot besteht, dringt widerrechtlich ein.", e: "Die allgemeine Zutrittserlaubnis gilt nicht für Personen mit Hausverbot.", r: "§ 123 StGB" },
  { u: "ordnung", t: "tf", d: 2, a: false, q: "Hausfriedensbruch setzt voraus, dass der Täter etwas beschädigt oder stiehlt.", e: "Es genügt das widerrechtliche Eindringen oder das Verweilen trotz Aufforderung.", r: "§ 123 StGB" },

  { u: "person", d: 1, q: "Was ist eine Körperverletzung nach § 223 StGB?", o: ["Die körperliche Misshandlung oder Gesundheitsschädigung einer anderen Person", ["Jede Beleidigung", "Die Beleidigung ist in § 185 StGB geregelt."], ["Die Beschädigung einer Sache", "Das ist Sachbeschädigung."], ["Das Festhalten einer Person ohne Schmerzen", "Das kann Freiheitsberaubung oder Nötigung sein."]], e: "Körperliche Misshandlung ist jede üble, unangemessene Behandlung, die das körperliche Wohlbefinden nicht nur unerheblich beeinträchtigt.", r: "§ 223 StGB" },
  { u: "person", t: "mc", d: 2, q: "Welche zwei Begehungsweisen machen eine Körperverletzung zur gefährlichen Körperverletzung (§ 224 StGB)?", o: ["Mittels einer Waffe oder eines anderen gefährlichen Werkzeugs", "Mit einem anderen Beteiligten gemeinschaftlich", ["Mit der flachen Hand", "Das ist eine einfache Körperverletzung."], ["Durch eine Beleidigung", "Das ist keine Körperverletzung."]], e: "Weitere Varianten: Gift, hinterlistiger Überfall, lebensgefährdende Behandlung.", r: "§ 224 StGB" },
  { u: "person", d: 2, f: 1, q: "Bei einer Rangelei schlägt eine Wachperson einem Störer mit der schweren Stabtaschenlampe auf den Arm. Welcher Tatbestand kommt – ohne Rechtfertigung – in Betracht?", o: ["Gefährliche Körperverletzung (§ 224 StGB)", ["Einfache Körperverletzung (§ 223 StGB)", "Die Taschenlampe wird als gefährliches Werkzeug eingesetzt."], ["Sachbeschädigung (§ 303 StGB)", "Betroffen ist ein Mensch, keine Sache."], ["Nötigung (§ 240 StGB)", "Im Vordergrund steht die Verletzung."]], e: "Ein Gegenstand ist ein gefährliches Werkzeug, wenn er nach Beschaffenheit und Art der Verwendung erhebliche Verletzungen herbeiführen kann.", r: "§ 224 Abs. 1 Nr. 2 StGB" },
  { u: "person", d: 2, q: "Wodurch unterscheidet sich die schwere Körperverletzung (§ 226 StGB)?", o: ["Durch schwere Folgen, z. B. Verlust des Sehvermögens oder eines wichtigen Glieds", ["Durch den Einsatz einer Waffe", "Das ist die gefährliche Körperverletzung."], ["Durch Fahrlässigkeit", "Das ist § 229 StGB."], ["Durch die Tatzeit bei Nacht", "Die Tatzeit spielt keine Rolle."]], e: "§ 226 StGB knüpft an die Folge an und ist mit Freiheitsstrafe von einem Jahr bis zu zehn Jahren bedroht – ein Verbrechen.", r: "§ 226 StGB" },
  { u: "person", d: 2, f: 1, q: "Eine Wachperson lässt beim Abschließen aus Unachtsamkeit ein schweres Tor zufallen und verletzt einen Mitarbeiter an der Hand. Welcher Tatbestand kommt in Betracht?", o: ["Fahrlässige Körperverletzung (§ 229 StGB)", ["Gefährliche Körperverletzung (§ 224 StGB)", "Es fehlt der Vorsatz."], ["Freiheitsberaubung (§ 239 StGB)", "Niemand wird eingesperrt."], ["Kein Tatbestand, weil keine Absicht bestand", "Fahrlässige Körperverletzung ist strafbar."]], e: "Wer durch Fahrlässigkeit die Körperverletzung einer anderen Person verursacht, macht sich strafbar.", r: "§ 229 StGB" },
  { u: "person", d: 1, q: "Was ist Freiheitsberaubung (§ 239 StGB)?", o: ["Einen Menschen einsperren oder auf andere Weise der Freiheit berauben", ["Jemandem den Weg erklären", "Das ist keine Freiheitsberaubung."], ["Jemanden beleidigen", "Das ist § 185 StGB."], ["Jemandem etwas wegnehmen", "Das ist Diebstahl."]], e: "Geschützt ist die Fortbewegungsfreiheit. Ein Festhalten ohne Rechtfertigungsgrund erfüllt den Tatbestand.", r: "§ 239 StGB" },
  { u: "person", d: 2, q: "Wann liegt eine Nötigung (§ 240 StGB) vor?", o: ["Wenn jemand einen Menschen rechtswidrig mit Gewalt oder durch Drohung mit einem empfindlichen Übel zu einer Handlung, Duldung oder Unterlassung zwingt", ["Wenn jemand höflich um etwas bittet", "Eine Bitte ist kein Zwang."], ["Wenn jemand ein Hausverbot ausspricht", "Die rechtmäßige Ausübung des Hausrechts ist nicht verwerflich."], ["Wenn jemand eine Strafanzeige erstattet", "Eine berechtigte Anzeige ist nicht rechtswidrig."]], e: "Rechtswidrig ist die Tat, wenn Gewalt oder Drohung zu dem angestrebten Zweck als verwerflich anzusehen ist.", r: "§ 240 StGB" },
  { u: "person", d: 3, f: 1, q: "Ein Detektiv sagt zu einer Verdächtigen: „Wenn Sie nicht sofort ein Geständnis unterschreiben, rufe ich Ihren Arbeitgeber an und erzähle allen, dass Sie eine Diebin sind.“ Welcher Tatbestand kommt in Betracht?", o: ["Nötigung (§ 240 StGB)", ["Körperverletzung (§ 223 StGB)", "Es wird niemand verletzt."], ["Hausfriedensbruch (§ 123 StGB)", "Es dringt niemand ein."], ["Kein Tatbestand – das ist übliche Praxis", "Solcher Druck ist unzulässig."]], e: "Die Drohung mit Bloßstellung ist ein empfindliches Übel; der Zweck, ein Geständnis zu erzwingen, ist verwerflich.", r: "§ 240 StGB" },
  { u: "person", d: 1, q: "Wie wird die Beleidigung (§ 185 StGB) verfolgt?", o: ["Grundsätzlich nur auf Antrag des Verletzten", ["Immer von Amts wegen", "Die Beleidigung ist ein Antragsdelikt (§ 194 StGB)."], ["Gar nicht", "Sie ist strafbar."], ["Nur, wenn sie schriftlich erfolgte", "Auch mündliche und tätliche Beleidigungen sind erfasst."]], e: "Beleidigung ist die Kundgabe von Missachtung oder Nichtachtung.", r: "§§ 185, 194 StGB" },
  { u: "person", t: "mc", d: 2, q: "Welche zwei Delikte richten sich gegen die persönliche Freiheit?", o: ["Freiheitsberaubung (§ 239 StGB)", "Nötigung (§ 240 StGB)", ["Unterschlagung (§ 246 StGB)", "Das ist ein Eigentumsdelikt."], ["Urkundenfälschung (§ 267 StGB)", "Sie schützt den Rechtsverkehr."]], e: "Der 18. Abschnitt des StGB schützt die persönliche Freiheit.", r: "§§ 239, 240 StGB" },
  { u: "person", t: "tf", d: 2, a: true, q: "Die einfache Körperverletzung wird nur auf Antrag verfolgt, es sei denn, die Staatsanwaltschaft bejaht ein besonderes öffentliches Interesse.", e: "Das regelt § 230 StGB; man spricht von einem relativen Antragsdelikt.", r: "§ 230 StGB" },
  { u: "person", t: "tf", d: 2, a: false, q: "Wer einen Ladendieb nach § 127 Abs. 1 StPO rechtmäßig festhält, begeht eine strafbare Freiheitsberaubung.", e: "Der Tatbestand ist erfüllt, die Tat ist aber durch das Festnahmerecht gerechtfertigt.", r: "§ 239 StGB; § 127 Abs. 1 StPO" },
  { u: "person", t: "zu", d: 2, q: "Ordne jeder Handlung den passenden Tatbestand zu.", p: [["Faustschlag ins Gesicht", "§ 223 StGB"], ["Schlag mit einer Flasche", "§ 224 StGB"], ["Einsperren im Lagerraum", "§ 239 StGB"], ["„Du Idiot!“", "§ 185 StGB"]], e: "Körperverletzung, gefährliche Körperverletzung, Freiheitsberaubung und Beleidigung sind die im Wachdienst häufigsten Delikte gegen die Person." },

  { u: "vermoegen", d: 1, q: "Was ist Diebstahl (§ 242 StGB)?", o: ["Die Wegnahme einer fremden beweglichen Sache in der Absicht, sie sich oder einem Dritten rechtswidrig zuzueignen", ["Die Zueignung einer Sache, die man bereits in Besitz hat", "Das ist Unterschlagung."], ["Die Wegnahme mit Gewalt gegen eine Person", "Das ist Raub."], ["Die Täuschung, um einen Vermögensvorteil zu erlangen", "Das ist Betrug."]], e: "Wegnahme ist der Bruch fremden und die Begründung neuen Gewahrsams.", r: "§ 242 StGB" },
  { u: "vermoegen", d: 2, q: "Worin unterscheidet sich die Unterschlagung (§ 246 StGB) vom Diebstahl?", o: ["Bei der Unterschlagung fehlt die Wegnahme – der Täter eignet sich eine Sache zu, die er bereits hat oder gefunden hat.", ["Bei der Unterschlagung wird Gewalt angewendet.", "Gewalt kennzeichnet den Raub."], ["Die Unterschlagung betrifft nur Geld.", "Sie betrifft jede fremde bewegliche Sache."], ["Die Unterschlagung ist straflos.", "Sie ist strafbar."]], e: "Typische Fälle: Fundunterschlagung, Behalten geliehener oder anvertrauter Sachen.", r: "§ 246 StGB" },
  { u: "vermoegen", d: 2, f: 1, q: "Ein Kunde steckt im Supermarkt eine Packung Rasierklingen in die Innentasche seiner Jacke und geht weiter durch die Regale. Wie ist die Lage nach der Rechtsprechung zu bewerten?", o: ["Der Diebstahl ist in der Regel bereits vollendet, weil er mit dem Einstecken eigenen Gewahrsam begründet hat.", ["Es liegt noch keine Straftat vor, solange er die Kasse nicht passiert hat.", "Bei kleinen Sachen in der Kleidung ist die Wegnahme bereits vollendet."], ["Es liegt nur eine Ordnungswidrigkeit vor.", "Diebstahl ist eine Straftat."], ["Es liegt Raub vor.", "Es fehlt Gewalt gegen eine Person."]], e: "Durch das Einstecken in die Kleidung entsteht eine Gewahrsamsenklave. In der Praxis wartet der Detektiv dennoch bis nach der Kasse, um den Vorsatz sicher nachweisen zu können.", r: "§ 242 StGB" },
  { u: "vermoegen", t: "mc", d: 2, q: "Welche zwei Umstände begründen in der Regel einen besonders schweren Fall des Diebstahls (§ 243 StGB)?", o: ["Einbrechen oder Einsteigen in ein Gebäude oder einen umschlossenen Raum", "Gewerbsmäßiges Stehlen", ["Stehlen einer Tafel Schokolade im Selbstbedienungsladen", "Bei geringwertigen Sachen ist ein besonders schwerer Fall ausgeschlossen."], ["Stehlen am Tag statt in der Nacht", "Die Tageszeit ist kein Regelbeispiel."]], e: "Weitere Regelbeispiele: Überwinden einer Schutzvorrichtung, Stehlen aus einem verschlossenen Behältnis.", r: "§ 243 StGB" },
  { u: "vermoegen", d: 3, q: "Was erfasst § 244 StGB?", o: ["Diebstahl mit Waffen, Bandendiebstahl und Wohnungseinbruchdiebstahl", ["Diebstahl geringwertiger Sachen", "Das regelt § 248a StGB."], ["Den unbefugten Gebrauch eines Fahrzeugs", "Das regelt § 248b StGB."], ["Die Hehlerei", "Das regelt § 259 StGB."]], e: "Wer beim Diebstahl eine Waffe oder ein anderes gefährliches Werkzeug bei sich führt, erfüllt § 244 StGB – auch ohne sie einzusetzen.", r: "§ 244 StGB" },
  { u: "vermoegen", d: 2, q: "Was gilt für den Diebstahl geringwertiger Sachen (§ 248a StGB)?", o: ["Er wird nur auf Antrag verfolgt, es sei denn, es besteht ein besonderes öffentliches Interesse.", ["Er ist straflos.", "Er bleibt strafbar."], ["Er ist eine Ordnungswidrigkeit.", "Er bleibt eine Straftat."], ["Er wird immer von Amts wegen verfolgt.", "Grundsätzlich ist ein Antrag nötig."]], e: "§ 248a StGB gilt für Diebstahl und Unterschlagung geringwertiger Sachen.", r: "§ 248a StGB" },
  { u: "vermoegen", d: 2, q: "Was unterscheidet den Raub (§ 249 StGB) vom Diebstahl?", o: ["Die Wegnahme erfolgt mit Gewalt gegen eine Person oder unter Drohung mit gegenwärtiger Gefahr für Leib oder Leben.", ["Die Beute ist wertvoller.", "Der Wert ist nicht entscheidend."], ["Die Tat geschieht bei Nacht.", "Die Tatzeit ist nicht entscheidend."], ["Der Täter ist maskiert.", "Maskierung ist kein Tatbestandsmerkmal."]], e: "Raub ist ein Verbrechen mit Mindeststrafe von einem Jahr.", r: "§ 249 StGB" },
  { u: "vermoegen", d: 3, f: 1, q: "Ein Ladendieb wird am Ausgang vom Detektiv angesprochen. Er schlägt den Detektiv nieder, um mit der Ware zu entkommen. Welcher Tatbestand ist erfüllt?", o: ["Räuberischer Diebstahl (§ 252 StGB)", ["Raub (§ 249 StGB)", "Beim Raub dient die Gewalt der Wegnahme, hier der Sicherung der Beute."], ["Einfacher Diebstahl (§ 242 StGB)", "Die Gewalt zur Beutesicherung macht daraus § 252 StGB."], ["Unterschlagung (§ 246 StGB)", "Es liegt eine Wegnahme vor."]], e: "Wer, bei einem Diebstahl auf frischer Tat betroffen, Gewalt anwendet, um sich im Besitz des gestohlenen Gutes zu erhalten, wird gleich einem Räuber bestraft.", r: "§ 252 StGB" },
  { u: "vermoegen", d: 2, q: "Was kennzeichnet den Betrug (§ 263 StGB)?", o: ["Der Täter täuscht, erregt dadurch einen Irrtum und veranlasst eine Vermögensverfügung, die zu einem Schaden führt.", ["Der Täter nimmt eine Sache heimlich weg.", "Das ist Diebstahl."], ["Der Täter wendet Gewalt an.", "Das kennzeichnet Raub oder Erpressung."], ["Der Täter beschädigt eine Sache.", "Das ist Sachbeschädigung."]], e: "Beispiel: Umetikettieren von Ware, um an der Kasse weniger zu zahlen.", r: "§ 263 StGB" },
  { u: "vermoegen", d: 2, q: "Was ist Hehlerei (§ 259 StGB)?", o: ["Eine Sache, die ein anderer gestohlen oder sonst rechtswidrig erlangt hat, ankaufen, sich verschaffen, absetzen oder absetzen helfen, um sich zu bereichern", ["Eine gefundene Sache behalten", "Das ist Unterschlagung."], ["Eine Sache mit Gewalt wegnehmen", "Das ist Raub."], ["Eine Urkunde fälschen", "Das ist § 267 StGB."]], e: "Der Hehler erhält die rechtswidrige Vermögenslage aufrecht.", r: "§ 259 StGB" },
  { u: "vermoegen", d: 3, q: "Was unterscheidet die Erpressung (§ 253 StGB) vom Raub?", o: ["Bei der Erpressung wird das Opfer durch Gewalt oder Drohung zu einer eigenen vermögensschädigenden Handlung genötigt; beim Raub nimmt der Täter selbst weg.", ["Erpressung ist immer straflos.", "Sie ist strafbar."], ["Erpressung erfordert keinen Vermögensschaden.", "Ein Vermögensnachteil gehört zum Tatbestand."], ["Erpressung betrifft nur Unternehmen.", "Opfer kann jeder sein."]], e: "Bei Gewalt gegen eine Person oder Drohung mit gegenwärtiger Gefahr für Leib oder Leben liegt räuberische Erpressung (§ 255 StGB) vor.", r: "§§ 253, 255 StGB" },
  { u: "vermoegen", t: "mc", d: 2, q: "Welche zwei Merkmale gehören zum Tatbestand des Diebstahls?", o: ["Fremde bewegliche Sache", "Zueignungsabsicht", ["Gewalt gegen eine Person", "Das ist ein Merkmal des Raubes."], ["Täuschung", "Das ist ein Merkmal des Betruges."]], e: "Hinzu kommt die Wegnahme.", r: "§ 242 StGB" },
  { u: "vermoegen", t: "mc", d: 3, q: "In welchen zwei Fällen liegt Unterschlagung und nicht Diebstahl vor?", o: ["Eine Wachperson behält eine im Dienst gefundene Uhr für sich.", "Ein Mitarbeiter verkauft den ihm überlassenen Dienstlaptop auf eigene Rechnung.", ["Ein Besucher steckt im Büro ein fremdes Handy vom Schreibtisch ein.", "Hier bricht er fremden Gewahrsam – Diebstahl."], ["Ein Kunde nimmt Ware aus dem Regal und verlässt den Laden ohne zu zahlen.", "Hier bricht er fremden Gewahrsam – Diebstahl."]], e: "Unterschlagung: Der Täter hat die Sache bereits oder niemand hat Gewahrsam; es fehlt der Gewahrsamsbruch.", r: "§§ 242, 246 StGB" },
  { u: "vermoegen", t: "tf", d: 1, a: true, q: "Der Versuch des Diebstahls ist strafbar.", e: "§ 242 Abs. 2 StGB bestimmt dies ausdrücklich.", r: "§ 242 Abs. 2 StGB" },
  { u: "vermoegen", t: "tf", d: 2, a: false, q: "Wer ohne Fahrschein mit der Bahn fährt, begeht einen Diebstahl.", e: "In Betracht kommt das Erschleichen von Leistungen (§ 265a StGB). Eine Sache wird nicht weggenommen.", r: "§ 265a StGB" },
  { u: "vermoegen", t: "zu", d: 2, q: "Ordne jedem Fall den passenden Tatbestand zu.", p: [["Wegnahme ohne Gewalt", "Diebstahl"], ["Wegnahme mit Gewalt gegen eine Person", "Raub"], ["Zueignung einer gefundenen Sache", "Unterschlagung"], ["Täuschung an der Kasse durch vertauschte Preisschilder", "Betrug"]], e: "Die Abgrenzung dieser vier Delikte gehört zum Kernwissen." },
  { u: "vermoegen", t: "fa", d: 3, q: "Grenze Diebstahl, Unterschlagung, Raub und räuberischen Diebstahl voneinander ab.", m: "Diebstahl (§ 242): Wegnahme einer fremden beweglichen Sache in Zueignungsabsicht, ohne Gewalt. Unterschlagung (§ 246): rechtswidrige Zueignung einer fremden beweglichen Sache ohne Wegnahme, weil der Täter sie schon hat oder gefunden hat. Raub (§ 249): Wegnahme mit Gewalt gegen eine Person oder Drohung mit gegenwärtiger Gefahr für Leib oder Leben – die Gewalt dient der Wegnahme. Räuberischer Diebstahl (§ 252): Der Dieb wird auf frischer Tat betroffen und setzt Gewalt oder Drohung ein, um sich im Besitz der Beute zu erhalten – die Gewalt dient der Sicherung. Raub und räuberischer Diebstahl sind Verbrechen.", c: ["Diebstahl: Wegnahme", "Unterschlagung: keine Wegnahme", "Raub: Gewalt zur Wegnahme", "§ 252: Gewalt zur Beutesicherung", "Verbrechen / Vergehen"] },

  { u: "sonst", d: 1, q: "Was ist Sachbeschädigung (§ 303 StGB)?", o: ["Das rechtswidrige Beschädigen oder Zerstören einer fremden Sache", ["Das Beschädigen der eigenen Sache", "Die Sache muss fremd sein."], ["Das fahrlässige Umstoßen eines Glases", "§ 303 StGB setzt Vorsatz voraus."], ["Das Wegnehmen einer fremden Sache", "Das ist Diebstahl."]], e: "Auch das unbefugte, nicht nur unerhebliche und nicht nur vorübergehende Verändern des Erscheinungsbilds (z. B. Graffiti) ist erfasst.", r: "§ 303 StGB" },
  { u: "sonst", d: 2, q: "Wann macht sich jemand wegen unterlassener Hilfeleistung (§ 323c StGB) strafbar?", o: ["Wenn er bei Unglücksfällen oder gemeiner Gefahr oder Not nicht Hilfe leistet, obwohl dies erforderlich und ihm zuzumuten ist", ["Immer, wenn er an einem Unfall vorbeikommt", "Die Hilfe muss erforderlich und zumutbar sein."], ["Nur, wenn er Arzt ist", "Die Pflicht trifft jedermann."], ["Nur, wenn er den Unfall verursacht hat", "Die Pflicht besteht unabhängig von der Verursachung."]], e: "Zumutbar ist Hilfe insbesondere, wenn sie ohne erhebliche eigene Gefahr und ohne Verletzung anderer wichtiger Pflichten möglich ist. Ein Notruf ist fast immer zumutbar.", r: "§ 323c StGB" },
  { u: "sonst", d: 2, f: 1, q: "Ein Besucher fälscht auf einem Passierschein das Datum, um erneut Zutritt zum Werk zu erhalten. Welcher Tatbestand kommt in Betracht?", o: ["Urkundenfälschung (§ 267 StGB)", ["Diebstahl (§ 242 StGB)", "Es wird nichts weggenommen."], ["Sachbeschädigung (§ 303 StGB)", "Im Vordergrund steht die Täuschung im Rechtsverkehr."], ["Beleidigung (§ 185 StGB)", "Es liegt keine Ehrverletzung vor."]], e: "Wer zur Täuschung im Rechtsverkehr eine echte Urkunde verfälscht oder eine verfälschte Urkunde gebraucht, begeht Urkundenfälschung.", r: "§ 267 StGB" },
  { u: "sonst", d: 2, q: "Was unterscheidet die falsche uneidliche Aussage (§ 153 StGB) vom Meineid (§ 154 StGB)?", o: ["Beim Meineid wird die falsche Aussage beschworen; er ist ein Verbrechen.", ["Beim Meineid lügt der Angeklagte.", "Beide Delikte betreffen Zeugen oder Sachverständige."], ["Die uneidliche Falschaussage ist straflos.", "Sie ist strafbar."], ["Es gibt keinen Unterschied.", "Der Eid führt zu einem höheren Strafrahmen."]], e: "Wer vor Gericht als Zeuge falsch aussagt, macht sich strafbar; unter Eid drohen mindestens ein Jahr Freiheitsstrafe.", r: "§§ 153, 154 StGB" },
  { u: "sonst", d: 2, q: "Was stellt § 164 StGB (falsche Verdächtigung) unter Strafe?", o: ["Einen anderen wider besseres Wissen bei einer Behörde einer rechtswidrigen Tat zu verdächtigen, um ein Verfahren gegen ihn herbeizuführen", ["Eine Anzeige zu erstatten, die sich später als unbegründet erweist", "Wer gutgläubig anzeigt, macht sich nicht strafbar."], ["Einen Verdacht für sich zu behalten", "Das ist nicht strafbar."], ["Als Zeuge die Aussage zu verweigern", "Das regelt § 164 StGB nicht."]], e: "Entscheidend ist „wider besseres Wissen“.", r: "§ 164 StGB" },
  { u: "sonst", t: "mc", d: 2, q: "Welche zwei Delikte sind typische Antragsdelikte?", o: ["Hausfriedensbruch (§ 123 StGB)", "Sachbeschädigung (§ 303 StGB)", ["Raub (§ 249 StGB)", "Raub ist ein Offizialdelikt."], ["Meineid (§ 154 StGB)", "Meineid ist ein Offizialdelikt."]], e: "Die Sachbeschädigung wird auf Antrag oder bei besonderem öffentlichen Interesse verfolgt (§ 303c StGB).", r: "§§ 123, 303c StGB" },
  { u: "sonst", t: "tf", d: 2, a: true, q: "Wer bei einem Unglücksfall eine Person behindert, die Hilfe leistet oder leisten will, macht sich ebenfalls nach § 323c StGB strafbar.", e: "§ 323c Abs. 2 StGB erfasst das Behindern hilfeleistender Personen, z. B. von Rettungskräften.", r: "§ 323c Abs. 2 StGB" },
  { u: "sonst", t: "tf", d: 2, a: false, q: "Wer als Zeuge vor Gericht bewusst falsch aussagt, bleibt straffrei, solange er nicht vereidigt wird.", e: "Schon die falsche uneidliche Aussage ist nach § 153 StGB strafbar.", r: "§ 153 StGB" },

  { u: "verfahren", d: 1, q: "Wo kann eine Strafanzeige erstattet werden?", o: ["Bei der Polizei, der Staatsanwaltschaft oder dem Amtsgericht", ["Nur beim Ordnungsamt", "Das Ordnungsamt ist dafür nicht die gesetzlich genannte Stelle."], ["Nur bei der IHK", "Die IHK nimmt keine Strafanzeigen entgegen."], ["Nur beim Arbeitgeber", "Der Arbeitgeber ist keine Strafverfolgungsbehörde."]], e: "§ 158 StPO nennt Staatsanwaltschaft, Behörden und Beamte des Polizeidienstes sowie die Amtsgerichte. Jeder kann Anzeige erstatten; die aufnehmende Stelle protokolliert oder dokumentiert sie.", r: "§ 158 StPO" },
  { u: "verfahren", d: 2, q: "Was unterscheidet den Strafantrag von der Strafanzeige?", o: ["Der Strafantrag ist die Erklärung des Verletzten, dass er die Strafverfolgung wünscht; die Anzeige ist nur die Mitteilung eines Sachverhalts.", ["Es gibt keinen Unterschied.", "Die Begriffe haben unterschiedliche Bedeutung."], ["Den Strafantrag stellt die Polizei.", "Antragsberechtigt ist grundsätzlich der Verletzte."], ["Die Strafanzeige ist nur schriftlich möglich.", "Sie kann auch mündlich erstattet werden."]], e: "Bei Antragsdelikten ist der Strafantrag Voraussetzung der Verfolgung.", r: "§ 77 StGB; § 158 StPO" },
  { u: "verfahren", d: 2, q: "Innerhalb welcher Frist muss ein Strafantrag gestellt werden?", o: ["Innerhalb von drei Monaten, nachdem der Berechtigte von Tat und Täter Kenntnis erlangt hat", ["Innerhalb von 24 Stunden", "Die Frist beträgt drei Monate."], ["Innerhalb von zwei Wochen", "Die Frist beträgt drei Monate."], ["Innerhalb von drei Jahren", "Die Frist beträgt drei Monate."]], e: "§ 77b StGB. Nach Fristablauf kann ein absolutes Antragsdelikt nicht mehr verfolgt werden.", r: "§ 77b StGB" },
  { u: "verfahren", d: 2, q: "Was ist ein Offizialdelikt?", o: ["Eine Straftat, die von Amts wegen verfolgt wird, sobald die Behörden davon erfahren", ["Eine Straftat, die nur Beamte begehen können", "Das ist ein Amtsdelikt."], ["Eine Straftat, die nur auf Antrag verfolgt wird", "Das ist ein Antragsdelikt."], ["Eine Ordnungswidrigkeit", "Offizialdelikte sind Straftaten."]], e: "Die meisten Straftaten sind Offizialdelikte, z. B. Diebstahl und Raub.", r: "§ 152 Abs. 2 StPO" },
  { u: "verfahren", d: 2, q: "Wer ist „Herrin des Ermittlungsverfahrens“?", o: ["Die Staatsanwaltschaft", ["Die Polizei", "Die Polizei ermittelt, die Leitung liegt bei der Staatsanwaltschaft."], ["Das Ordnungsamt", "Es ist für Ordnungswidrigkeiten und Gefahrenabwehr zuständig."], ["Der Geschädigte", "Er ist Zeuge bzw. Verletzter."]], e: "Die Staatsanwaltschaft leitet das Ermittlungsverfahren und entscheidet über Anklage oder Einstellung.", r: "§§ 152, 160, 163 StPO" },
  { u: "verfahren", t: "mc", d: 2, q: "Welche zwei Pflichten hat ein Zeuge vor Gericht?", o: ["Er muss erscheinen.", "Er muss wahrheitsgemäß aussagen.", ["Er muss den Angeklagten belasten.", "Er muss die Wahrheit sagen, gleich zu wessen Gunsten."], ["Er muss ein Urteil vorschlagen.", "Das ist Aufgabe des Gerichts."]], e: "§ 48 StPO: Zeugen müssen erscheinen und aussagen. Vor der Vernehmung werden sie zur Wahrheit ermahnt (§ 57 StPO). Bei Ausbleiben drohen Kosten, Ordnungsgeld und Vorführung (§ 51 StPO).", r: "§§ 48, 51, 57 StPO" },
  { u: "verfahren", d: 2, q: "Wer darf als Zeuge das Zeugnis nach § 52 StPO verweigern?", o: ["Nahe Angehörige des Beschuldigten, z. B. Ehegatten und Verlobte", ["Jeder, der keine Zeit hat", "Zeitmangel ist kein Grund."], ["Jede Wachperson", "Ein berufsbezogenes Verweigerungsrecht haben Wachpersonen nicht."], ["Jeder Kollege des Beschuldigten", "Kollegen sind keine Angehörigen."]], e: "Daneben darf jeder Zeuge die Auskunft auf Fragen verweigern, deren Beantwortung ihn selbst oder einen Angehörigen der Gefahr der Strafverfolgung aussetzen würde (§ 55 StPO).", r: "§§ 52, 55 StPO" },
  { u: "verfahren", d: 2, q: "Welches Recht hat ein Beschuldigter bei seiner Vernehmung?", o: ["Er darf schweigen und jederzeit einen Verteidiger befragen.", ["Er muss sich selbst belasten.", "Niemand muss sich selbst belasten."], ["Er hat keine Rechte, solange er nicht angeklagt ist.", "Die Rechte bestehen ab der ersten Vernehmung."], ["Er darf die Ermittlungsakten vernichten.", "Ein solches Recht gibt es nicht."]], e: "§ 136 StPO: Belehrung über den Tatvorwurf, das Schweigerecht und das Recht auf Verteidigerkonsultation.", r: "§ 136 StPO" },
  { u: "verfahren", d: 2, f: 1, q: "Eine Wachperson wird als Zeugin eines Diebstahls zur Hauptverhandlung geladen. Sie kann sich an Details nicht mehr sicher erinnern. Wie verhält sie sich richtig?", o: ["Sie sagt wahrheitsgemäß aus und macht deutlich, woran sie sich sicher erinnert und woran nicht.", ["Sie füllt Lücken mit Vermutungen, damit die Aussage rund wirkt.", "Vermutungen als Tatsachen darzustellen kann eine Falschaussage sein."], ["Sie bleibt der Verhandlung fern.", "Es besteht Erscheinenspflicht."], ["Sie sagt, was der Arbeitgeber hören möchte.", "Maßgeblich ist allein die Wahrheit."]], e: "Ein zeitnah gefertigter Bericht hilft, die Erinnerung aufzufrischen. Erinnerungslücken sind offen zu benennen.", r: "§§ 48, 57 StPO; § 153 StGB" },
  { u: "verfahren", t: "tf", d: 2, a: true, q: "Bei einem Antragsdelikt kann der Verletzte den Strafantrag bis zum rechtskräftigen Abschluss des Verfahrens zurücknehmen.", e: "§ 77d StGB. Ein zurückgenommener Antrag kann nicht nochmals gestellt werden.", r: "§ 77d StGB" },
  { u: "verfahren", t: "tf", d: 1, a: false, q: "Privatpersonen sind allgemein verpflichtet, jede Straftat anzuzeigen, von der sie erfahren.", e: "Eine allgemeine Anzeigepflicht besteht nicht. Strafbar ist nur die Nichtanzeige bestimmter geplanter schwerer Straftaten (§ 138 StGB). Für Wachpersonen können sich Meldepflichten aus der Dienstanweisung ergeben.", r: "§ 138 StGB" },
  { u: "verfahren", t: "fa", d: 2, q: "Erkläre die Begriffe Offizialdelikt, absolutes Antragsdelikt und relatives Antragsdelikt mit je einem Beispiel.", m: "Offizialdelikte werden von Amts wegen verfolgt, sobald die Strafverfolgungsbehörden davon erfahren, z. B. Diebstahl oder Raub. Absolute Antragsdelikte werden ausschließlich auf Strafantrag des Verletzten verfolgt, z. B. Hausfriedensbruch und Beleidigung. Relative Antragsdelikte werden grundsätzlich auf Antrag verfolgt, können aber auch ohne Antrag verfolgt werden, wenn die Staatsanwaltschaft ein besonderes öffentliches Interesse bejaht, z. B. einfache Körperverletzung, Sachbeschädigung, Diebstahl geringwertiger Sachen. Die Antragsfrist beträgt drei Monate.", c: ["Offizialdelikt + Beispiel", "absolutes Antragsdelikt + Beispiel", "relatives Antragsdelikt + Beispiel", "Frist drei Monate"] },
  { u: "verfahren", t: "fa", d: 2, q: "Welche Angaben gehören in einen guten Bericht bzw. eine Meldung über eine Straftat im Objekt?", m: "Wer hat was wann wo wie getan – und woher weiß ich das? Also: Datum, Uhrzeit und genauer Ort; beteiligte Personen und Zeugen mit Erreichbarkeit; sachliche, chronologische Schilderung der eigenen Wahrnehmungen, klar getrennt von Vermutungen und Hörensagen; getroffene Maßnahmen, z. B. Ansprache, Festhalten, Verständigung der Polizei mit Uhrzeit; sichergestellte Gegenstände und Schäden; Name des Verfassers und Unterschrift. Keine Wertungen, keine Abkürzungen, die Dritte nicht verstehen.", c: ["W-Fragen", "eigene Wahrnehmung vs. Vermutung", "Maßnahmen und Zeiten", "Zeugen", "sachlich, vollständig, zeitnah"] },

  { u: "btm", d: 2, q: "Was ist nach § 29 BtMG unter anderem strafbar?", o: ["Der unerlaubte Besitz, Erwerb, Anbau und Handel mit Betäubungsmitteln", ["Nur der Handel in großen Mengen", "Auch Besitz und Erwerb sind strafbar."], ["Nur der Konsum", "Der bloße Konsum ist nicht als solcher unter Strafe gestellt."], ["Nichts – das BtMG enthält nur Ordnungswidrigkeiten", "Es enthält Straftatbestände."]], e: "§ 29 Abs. 1 BtMG nennt u. a. Anbau, Herstellung, Handeltreiben, Erwerb und Besitz. Für Cannabis gilt seit 2024 das Konsumcannabisgesetz mit eigenen Verboten (§ 2 KCanG) und erlaubten Besitzmengen für Erwachsene (§ 3 KCanG).", r: "§ 29 Abs. 1 BtMG; §§ 2, 3 KCanG" },
  { u: "btm", d: 2, f: 1, q: "Bei der Einlasskontrolle entdeckt eine Wachperson in der freiwillig geöffneten Tasche eines Gastes ein Tütchen mit weißem Pulver. Wie handelt sie richtig?", o: ["Sie verweigert den Einlass, nimmt das Tütchen nicht an sich und verständigt nach der Dienstanweisung die Polizei.", ["Sie nimmt das Tütchen an sich und entsorgt es zu Hause.", "Damit hätte sie selbst unerlaubten Besitz."], ["Sie beschlagnahmt das Tütchen offiziell.", "Beschlagnahmen können nur Behörden."], ["Sie lässt den Gast mit dem Tütchen hinein.", "Das widerspricht dem Hausrecht und dem Schutzauftrag."]], e: "Wachpersonen dürfen Betäubungsmittel nicht dauerhaft in Besitz nehmen. Eine kurzfristige Sicherung zur Übergabe an die Polizei ist nach Dienstanweisung möglich.", r: "§ 29 BtMG; § 34a Abs. 5 GewO" },
  { u: "btm", d: 2, q: "Worin unterscheidet sich die Ordnungswidrigkeit von der Straftat?", o: ["Sie ist Verwaltungsunrecht und wird mit Geldbuße geahndet; es gilt das Opportunitätsprinzip.", ["Sie wird mit Freiheitsstrafe geahndet.", "Freiheitsstrafe gibt es nur bei Straftaten."], ["Sie wird immer vom Strafgericht verhandelt.", "Zuständig ist zunächst die Verwaltungsbehörde."], ["Sie führt immer zu einem Eintrag im Führungszeugnis.", "Bußgelder werden dort nicht eingetragen."]], e: "Grundlage ist das Gesetz über Ordnungswidrigkeiten (OWiG).", r: "§§ 1, 47 OWiG" },
  { u: "btm", t: "mc", d: 2, q: "Welche zwei Verstöße sind Ordnungswidrigkeiten und keine Straftaten?", o: ["Falschparken", "Betreiben eines Bewachungsgewerbes ohne Erlaubnis", ["Ladendiebstahl", "Das ist eine Straftat."], ["Körperverletzung", "Das ist eine Straftat."]], e: "Ordnungswidrigkeiten finden sich u. a. in StVO und § 144 GewO.", r: "§ 144 GewO; OWiG" },
  { u: "btm", t: "tf", d: 2, a: false, q: "Eine Wachperson darf bei einem Fund illegaler Drogen diese dauerhaft an sich nehmen, um sie später selbst zu vernichten.", e: "Der Besitz ohne Erlaubnis ist strafbar. Die Drogen sind unverzüglich der Polizei zu übergeben.", r: "§ 29 BtMG" },
  { u: "festnahme", t: "mc", d: 2, q: "Welche zwei Festnahmegründe nennt § 127 Abs. 1 StPO neben der frischen Tat?", o: ["Die Person ist der Flucht verdächtig.", "Ihre Identität kann nicht sofort festgestellt werden.", ["Die Person ist vorbestraft.", "Das ist kein Festnahmegrund."], ["Der Schaden übersteigt 50 Euro.", "Eine Wertgrenze gibt es nicht."]], e: "Einer der beiden Gründe muss zusätzlich zur frischen Tat vorliegen.", r: "§ 127 Abs. 1 StPO" },
  { u: "verfahren", t: "mc", d: 2, q: "Welche zwei Aussagen zum Strafantrag treffen zu?", o: ["Antragsberechtigt ist grundsätzlich der Verletzte.", "Die Antragsfrist beträgt drei Monate ab Kenntnis von Tat und Täter.", ["Der Strafantrag kann nur von der Polizei gestellt werden.", "Er wird vom Verletzten gestellt."], ["Der Strafantrag ist bei allen Straftaten Voraussetzung der Verfolgung.", "Er ist nur bei Antragsdelikten erforderlich."]], e: "§§ 77, 77b StGB.", r: "§§ 77, 77b StGB" },
  { u: "ordnung", t: "mc", d: 2, q: "Welche zwei Verhaltensweisen erfüllen den Tatbestand des Hausfriedensbruchs?", o: ["Widerrechtliches Eindringen in Geschäftsräume", "Verweilen ohne Befugnis trotz Aufforderung des Berechtigten, sich zu entfernen", ["Lautes Sprechen im Treppenhaus", "Das allein erfüllt den Tatbestand nicht."], ["Parken auf einer öffentlichen Straße vor dem Haus", "Dort besteht kein Hausrecht."]], e: "§ 123 Abs. 1 StGB kennt diese beiden Varianten.", r: "§ 123 StGB" },
  { u: "aufbau", t: "mc", d: 2, q: "Welche zwei Vorschriften sind strafrechtliche Rechtfertigungsgründe?", o: ["§ 32 StGB (Notwehr)", "§ 34 StGB (rechtfertigender Notstand)", ["§ 19 StGB (Schuldunfähigkeit des Kindes)", "Das ist ein Schuldausschließungsgrund."], ["§ 35 StGB (entschuldigender Notstand)", "Er entschuldigt, rechtfertigt aber nicht."]], e: "Rechtfertigungsgründe lassen die Rechtswidrigkeit entfallen, Entschuldigungsgründe nur die Schuld.", r: "§§ 32, 34 StGB" }
]);
